#!/usr/bin/env bash
# Generate eos_shim.def for the EOS proxy/shim DLL.
#
# The shim ships AS  EOSSDK-Win64-Shipping.dll  next to the game, and the genuine
# Epic SDK is copied to  EOSSDK-Win64-Shipping-pointed-to-by-shim.dll  (REAL_DLL below).
#
# Every symbol the game imports must be exported by the shim or the game won't
# load. Functions we intercept (HOOKED) are exported from our own object code;
# everything else is a zero-code loader FORWARD to the real DLL.
set -euo pipefail
cd "$(dirname "$0")"

IMPORTS="game_imports.txt"          # the 82 names the game's IAT binds
REAL_DLL="EOSSDK-Win64-Shipping-pointed-to-by-shim"  # forward target module (no .dll suffix)
# NOTE: must be DOT-FREE. The loader splits a forwarder string on the LAST '.'
# to separate module from function, then appends '.dll' ONLY if the module name
# has no extension. A name like 'EOSSDK-Win64-Shipping.orig' looks like it
# already has a '.orig' extension, so '.dll' is NOT appended and the forward
# fails -> instant crash at load. Hyphen avoids that.
OUT="eos_shim.def"

# Functions we implement ourselves (typed trampolines w/ logging + delegate wrap).
# Keep this list in sync with src/trampolines_*.cpp.
HOOKED=$(cat <<'EOF'
EOS_Connect_Login
EOS_Connect_AddNotifyLoginStatusChanged
EOS_Lobby_CreateLobby
EOS_Lobby_JoinLobby
EOS_Lobby_DestroyLobby
EOS_Lobby_LeaveLobby
EOS_Lobby_AddNotifyLobbyMemberStatusReceived
EOS_LobbySearch_SetLobbyId
EOS_LobbySearch_Find
EOS_P2P_AddNotifyPeerConnectionClosed
EOS_P2P_AddNotifyPeerConnectionRequest
EOS_P2P_SendPacket
EOS_P2P_ReceivePacket
EOS_P2P_AcceptConnection
EOS_P2P_CloseConnection
EOS_Initialize
EOS_Shutdown
EOF
)

is_hooked() { grep -qxF "$1" <<<"$HOOKED"; }

{
  echo "; AUTO-GENERATED by generate_def.sh -- do not edit by hand."
  echo "; Shim proxy for EOSSDK-Win64-Shipping.dll. Forwards to $REAL_DLL.dll"
  echo "LIBRARY EOSSDK-Win64-Shipping"
  echo "EXPORTS"
  while IFS= read -r fn; do
    [ -z "$fn" ] && continue
    if is_hooked "$fn"; then
      echo "    $fn"                       # exported from our code
    else
      echo "    $fn = $REAL_DLL.$fn"       # loader forwards straight through
    fi
  done < <(sort -u "$IMPORTS")
} > "$OUT"

hooked_n=$(grep -cvE ' = ' "$OUT" | head -1 || true)
total=$(grep -cE '^    ' "$OUT")
fwd=$(grep -cE ' = ' "$OUT")
echo "wrote $OUT: $total exports ($fwd forwarded, $((total-fwd)) hooked)"
